    print(k, len(d.get(k,[])))
bad=[]
for f in d['failure_modes']:
    for req in ['quote','loc','detector_candidate','rule_origin','name','era_class','detector_family','what_happened','user_intervention','outcome','detectable_by']:
        if not f.get(req): bad.append(('fm',f.get('name'),req))
for r in d['skill_rules']:
    for req in ['evidence','skill_target','overlap','rule_id','rule','because','because_source','feasibility','taught_or_enforced']:
        if not r.get(req): bad.append(('sr',r.get('rule_id'),req))
    if r.get('because_source')=='user-verbatim' and not r.get('quote'): bad.append(('sr-quote',r['rule_id'],'quote'))
for p in d['philosophy']:
    if p.get('source')=='user-verbatim' and not p.get('quote'): bad.append(('ph',p.get('loc'),'quote'))
for p in d['pairing_rules']:
    if p.get('because_source')=='user-verbatim' and not p.get('quote'): bad.append(('pr',p['rule_id'],'quote'))
    for req in ['rule_id','rule','class','because','because_source','evidence']:
        if not p.get(req): bad.append(('pr',p.get('rule_id'),req))
for c in d['council_episodes']:
    for req in ['loc','trigger','invoked_by','personas','voices','outcome','fidelity','user_reaction','lesson']:
        if not c.get(req): bad.append(('ce',c.get('loc'),req))
    for f in c['fidelity']:
        if not f.get('persona') or not f.get('assessment') or not f.get('evidence'): bad.append(('ce-fid',c.get('loc'),f.get('persona')))
print('PROBLEMS:', bad)
